/**
 * Retrieves the device's coarse coordinates from `LocationManager` if `ACCESS_COARSE_LOCATION`
 * is granted, or safely falls back to Latitude 10.51, Longitude 124.03 when denied or null.
 */
private fun resolveDeviceCoordinatesOrFallback(context: Context): Pair<Double, Double> {
  val fallback = DEFAULT_FALLBACK_LATITUDE to DEFAULT_FALLBACK_LONGITUDE
  val hasCoarsePermission = ContextCompat.checkSelfPermission(
    context,
    Manifest.permission.ACCESS_COARSE_LOCATION
  ) == PackageManager.PERMISSION_GRANTED

  if (!hasCoarsePermission) {
    return fallback
  }

  return try {
    val locationManager = context.getSystemService(Context.LOCATION_SERVICE) as? LocationManager
      ?: return fallback

    val providers = listOf(
      LocationManager.NETWORK_PROVIDER,
      LocationManager.PASSIVE_PROVIDER,
      LocationManager.GPS_PROVIDER
    )

    val lastKnownLocation = providers.firstNotNullOfOrNull { provider ->
      try {
        if (locationManager.isProviderEnabled(provider)) {
          locationManager.getLastKnownLocation(provider)
        } else {
          null
        }
      } catch (_: SecurityException) {
        null
      } catch (_: Exception) {
        null
      }
    }

    if (lastKnownLocation != null) {
      lastKnownLocation.latitude to lastKnownLocation.longitude
    } else {
      fallback
    }
  } catch (_: SecurityException) {
    fallback
  } catch (_: Exception) {
    fallback
  }
}

@Composable
fun CivilEngineeringProductivityApp(
  taskViewModel: TaskViewModel? = null
) {
  val context = LocalContext.current
  val storageManager = remember(context) {
    LocalStorageManager(context.applicationContext ?: context)
  }
  val resolvedViewModel: TaskViewModel = taskViewModel ?: viewModel(
    factory = TaskViewModel.provideFactory(storageManager)
  )
  remember(resolvedViewModel, storageManager) {
    resolvedViewModel.attachStorage(storageManager)
    true
  }

  // Dynamically switch between darkColorScheme() and lightColorScheme() based on ViewModel.isDarkMode
  val dynamicColorScheme = if (resolvedViewModel.isDarkMode) {
    CanvaDarkColorScheme
  } else {
    CanvaLightColorScheme
  }

  val animatedGlassPalette = rememberAnimatedGlassPalette(isDark = resolvedViewModel.isDarkMode)

  CompositionLocalProvider(LocalGlassPalette provides animatedGlassPalette) {
    MaterialTheme(
      colorScheme = dynamicColorScheme,
      typography = Typography
    ) {
      // Cross-Device Persistence & Auto-Login:
      // 1. On app launch, check val user = FirebaseAuth.getInstance().currentUser.
      // 2. If user != null OR isGuestMode == true: navigate straight to the Dashboard (bypassing Auth screen).
      // 3. If user == null AND !isGuestMode: show the Liquid Glass Auth Screen.
      val initialFirebaseUser = remember {
        try {
          FirebaseAuth.getInstance().currentUser
        } catch (_: Throwable) {
          getFirebaseAuthOrNull(context)?.currentUser
        }
      }
      var isGuestMode by rememberSaveable {
        mutableStateOf(resolvedViewModel.isGuestMode)
      }
      var isLoggedIn by rememberSaveable {
        mutableStateOf(initialFirebaseUser != null || isGuestMode)
      }

      LaunchedEffect(Unit) {
        val user = try {
          FirebaseAuth.getInstance().currentUser
        } catch (_: Throwable) {
          getFirebaseAuthOrNull(context)?.currentUser
        }
        if (user != null) {
          isGuestMode = false
          resolvedViewModel.restoreSessionFromFirebaseUser(user)
          isLoggedIn = true
        } else if (resolvedViewModel.isGuestMode || isGuestMode) {
          isGuestMode = true
          isLoggedIn = true
        } else {
          isLoggedIn = false
        }
        resolvedViewModel.startFirestoreSync()
      }

      // Observe auth.currentUser and connect real-time Firestore snapshot listeners for the workspace
      DisposableEffect(resolvedViewModel) {
        val auth = try {
          FirebaseAuth.getInstance()
        } catch (_: Throwable) {
          getFirebaseAuthOrNull(context)
        }
        val authListener = FirebaseAuth.AuthStateListener { firebaseAuth ->
          val currentUser = firebaseAuth.currentUser
          if (currentUser != null) {
            isGuestMode = false
            isLoggedIn = true
            resolvedViewModel.onAuthenticatedUserChanged(currentUser)
          }
        }
        auth?.addAuthStateListener(authListener)
        resolvedViewModel.startFirestoreSync()
        onDispose {
          auth?.removeAuthStateListener(authListener)
          resolvedViewModel.stopFirestoreSync()
        }
      }

      // Safety timeout so loading indicators never remain stuck if offline while logged in
      LaunchedEffect(resolvedViewModel.isFirestoreSyncing) {
        if (resolvedViewModel.isFirestoreSyncing) {
          delay(4_500L)
          resolvedViewModel.clearInitialSyncIndicators()
        }
      }

      Crossfade(
        targetState = isLoggedIn,
        animationSpec = tween(durationMillis = 300),
        label = "auth_to_main_transition"
      ) { loggedIn ->
        if (!loggedIn) {
          StartupLoginScreen(
            isDarkMode = resolvedViewModel.isDarkMode,
            onAttemptLogin = { typedEmail, typedPassword ->
              val result = resolvedViewModel.attemptLogin(typedEmail, typedPassword)
              if (result == LoginValidationResult.SUCCESS) {
                isGuestMode = false
                isLoggedIn = true
              }
              result
            },
            onFirebaseLoginSuccess = { loggedInEmail, firebaseDisplayName, enteredPassword ->
              isGuestMode = false
              if (
                enteredPassword.isNotBlank() &&
                !resolvedViewModel.isUsernameRegistered(loggedInEmail)
              ) {
                resolvedViewModel.completeSignUp(
                  usernameToRegister = loggedInEmail,
                  password = enteredPassword,
                  displayNameToRegister = firebaseDisplayName,
                  recoveryPinToRegister = ""
                )
              } else {
                resolvedViewModel.loginWithUsername(loggedInEmail, firebaseDisplayName)
              }
              isLoggedIn = true
            },
            onCheckUsernameRegistered = { emailToCheck ->
              resolvedViewModel.isUsernameRegistered(emailToCheck)
            },
            onCompleteSignUp = { registeredEmail, createdPassword, displayName, recoveryPin ->
              isGuestMode = false
              resolvedViewModel.completeSignUp(
                usernameToRegister = registeredEmail,
                password = createdPassword,
                displayNameToRegister = displayName,
                recoveryPinToRegister = recoveryPin
              )
              isLoggedIn = true
            },
            onContinueAsGuest = {
              isGuestMode = true
              resolvedViewModel.loginAsGuest()
              isLoggedIn = true
            }
          )
        } else {
          MainProductivityScaffold(
            taskViewModel = resolvedViewModel,
            onLogout = {
              try {
                FirebaseAuth.getInstance().signOut()
              } catch (_: Throwable) {
              }
              isGuestMode = false
              resolvedViewModel.logout()
              isLoggedIn = false
            }
          )
        }
      }
    }
  }
}

/**
 * Refined Liquid Glass Login & Sign-Up Screen with Real Email & Password Firebase Authentication:
 * - Centered responsive card (`Modifier.fillMaxWidth().widthIn(max = 440.dp).padding(20.dp)`).
 * - Frosted glass card with specular gradient border and subtle depth shadow.
 * - Animated segmented pill slider at the top of the card switching between `"Log In"` and `"Sign Up"`.
 * - Clean rounded glass input containers (`14.dp` corner radius) with glowing outline when active.
 * - Cloud Registration (Sign Up):
 *   1. Full Name / Nickname (`Icons.Default.Badge`)
 *   2. Email Address (`Icons.Default.Email`, `KeyboardType.Email`, `KeyboardCapitalization.None`)
 *   3. Password (`Icons.Default.Lock`, min 6 characters, eye toggle)
 * - Cloud Login (Log In):
 *   1. Email Address (`Icons.Default.Email`, `KeyboardType.Email`, `KeyboardCapitalization.None`)
 *   2. Password (`Icons.Default.Lock`, eye toggle)
 * - Submit Button (`"Sign In"` or `"Create Account"`) disabled while `isLoading` is true with a circular progress spinner.
 * - `"Continue as Offline Scholar →"` guest bypass at the bottom.
 */
/**
 * Custom `SibilCeAppIconBadge` emblem drawn via Compose `Canvas` to match the installed launcher icon:
 * - Glossy slate-blue rounded square emblem (`Color(0xFF1E3A5F)` to `Color(0xFF0F172A)`) with a top glass highlight.
 * - Rolled blue CAD blueprint scroll with engineering grid lines.
 * - Yellow Civil Engineering safety hard hat with crown ridge and visor brim.
 * - Yellow measuring tape with tick marks and an orange/gold drafting pencil.
 */
@Composable
fun SibilCeAppIconBadge(
  modifier: Modifier = Modifier,
  size: Dp = 64.dp
) {
  val badgeShape = RoundedCornerShape((size.value * 0.28f).dp)
  Box(
    modifier = modifier
      .size(size)
      .shadow(
        elevation = if (size >= 56.dp) 12.dp else 6.dp,
        shape = badgeShape,
        ambientColor = Color(0xFF0284C7).copy(alpha = 0.35f),
        spotColor = Color(0xFF1E3A8A).copy(alpha = 0.40f)
      )
      .clip(badgeShape)
      .border(
        width = 1.4.dp,
        brush = Brush.linearGradient(
          colors = listOf(
            Color.White.copy(alpha = 0.78f),
            Color(0xFF38BDF8).copy(alpha = 0.45f),
            Color(0xFF0F172A).copy(alpha = 0.60f)
          )
        ),
        shape = badgeShape
      )
      .testTag("sibil_ce_app_icon_badge")
  ) {
    Canvas(modifier = Modifier.fillMaxSize()) {
      val w = this.size.width
      val h = this.size.height

      // 1. Glossy Slate-Blue Base
      drawRect(
        brush = Brush.linearGradient(
          colors = listOf(
            Color(0xFF254B7C),
            Color(0xFF162C4E),
            Color(0xFF0B172A)
          ),
          start = Offset(0f, 0f),
          end = Offset(w, h)
        )
      )

      // Subtle inner cyan radial sheen
      drawCircle(
        brush = Brush.radialGradient(
          colors = listOf(
            Color(0xFF38BDF8).copy(alpha = 0.28f),
            Color.Transparent
          ),
          center = Offset(w * 0.28f, h * 0.24f),
          radius = w * 0.72f
        ),
        center = Offset(w * 0.28f, h * 0.24f),
        radius = w * 0.72f
      )

      // 2. Rolled Blue Blueprint Scroll (lower-left to upper-right diagonal sheet + curl)
      val bpLeft = w * 0.14f
      val bpTop = h * 0.42f
      val bpRight = w * 0.76f
      val bpBottom = h * 0.84f
      drawRoundRect(
        brush = Brush.linearGradient(
          colors = listOf(Color(0xFF0284C7), Color(0xFF0369A1)),
          start = Offset(bpLeft, bpTop),
          end = Offset(bpRight, bpBottom)
        ),
        topLeft = Offset(bpLeft, bpTop),
        size = Size(bpRight - bpLeft, bpBottom - bpTop),
        cornerRadius = CornerRadius(w * 0.08f, w * 0.08f)
      )
      drawRoundRect(
        color = Color(0xFFBAE6FD).copy(alpha = 0.75f),
        topLeft = Offset(bpLeft, bpTop),
        size = Size(bpRight - bpLeft, bpBottom - bpTop),
        cornerRadius = CornerRadius(w * 0.08f, w * 0.08f),
        style = Stroke(width = w * 0.022f)
      )
      // Blueprint CAD grid lines
      val gridColor = Color.White.copy(alpha = 0.42f)
      for (i in 1..3) {
        val gx = bpLeft + (bpRight - bpLeft) * (i / 4f)
        drawLine(
          color = gridColor,
          start = Offset(gx, bpTop + h * 0.04f),
          end = Offset(gx, bpBottom - h * 0.04f),
          strokeWidth = w * 0.015f
        )
      }
      for (i in 1..2) {
        val gy = bpTop + (bpBottom - bpTop) * (i / 3f)
        drawLine(
          color = gridColor,
          start = Offset(bpLeft + w * 0.04f, gy),
          end = Offset(bpRight - w * 0.04f, gy),
          strokeWidth = w * 0.015f
        )
      }
      // Rolled cylinder end on left of blueprint
      drawCircle(
        color = Color(0xFF7DD3FC),
        radius = w * 0.065f,
        center = Offset(bpLeft + w * 0.02f, (bpTop + bpBottom) * 0.5f)
      )
      drawCircle(
        color = Color(0xFF0C4A6E),
        radius = w * 0.028f,
        center = Offset(bpLeft + w * 0.02f, (bpTop + bpBottom) * 0.5f)
      )

      // 3. Drafting Pencil (angled across the right side)
      val pStart = Offset(w * 0.56f, h * 0.78f)
      val pEnd = Offset(w * 0.86f, h * 0.26f)
      drawLine(
        color = Color(0xFFF97316),
        start = pStart,
        end = pEnd,
        strokeWidth = w * 0.095f,
        cap = StrokeCap.Round
      )
      drawLine(
        color = Color(0xFFFDE047),
        start = pStart,
        end = pEnd,
        strokeWidth = w * 0.035f,
        cap = StrokeCap.Round
      )
      // Pencil tip cone
      drawCircle(
        color = Color(0xFFFDE68A),
        radius = w * 0.045f,
        center = pEnd
      )
      drawCircle(
        color = Color(0xFF1E293B),
        radius = w * 0.020f,
        center = Offset(pEnd.x + w * 0.015f, pEnd.y - h * 0.02f)
      )

      // 4. Tape Measure (bottom-right badge)
      val tapeCenter = Offset(w * 0.74f, h * 0.73f)
      drawCircle(
        brush = Brush.radialGradient(
          colors = listOf(Color(0xFFFACC15), Color(0xFFCA8A04)),
          center = tapeCenter,
          radius = w * 0.15f
        ),
        radius = w * 0.145f,
        center = tapeCenter
      )
      drawCircle(
        color = Color(0xFF1E293B),
        radius = w * 0.065f,
        center = tapeCenter
      )
      drawCircle(
        color = Color.White.copy(alpha = 0.85f),
        radius = w * 0.145f,
        center = tapeCenter,
        style = Stroke(width = w * 0.02f)
      )

      // 5. Yellow CE Hard Hat (upper-center dome + ridge + visor brim)
      val domeLeft = w * 0.18f
      val domeRight = w * 0.72f
      val domeTop = h * 0.15f
      val domeBottom = h * 0.54f
      drawArc(
        brush = Brush.verticalGradient(
          colors = listOf(Color(0xFFFEF08A), Color(0xFFFACC15), Color(0xFFEAB308)),
          startY = domeTop,
          endY = domeBottom
        ),
        startAngle = 180f,
        sweepAngle = 180f,
        useCenter = true,
        topLeft = Offset(domeLeft, domeTop),
        size = Size(domeRight - domeLeft, (domeBottom - domeTop) * 1.45f)
      )
      // Hard hat central crown ridge
      val ridgeCenter = (domeLeft + domeRight) * 0.5f
      drawRoundRect(
        color = Color(0xFFFEF9C3),
        topLeft = Offset(ridgeCenter - w * 0.045f, domeTop - h * 0.02f),
        size = Size(w * 0.09f, h * 0.22f),
        cornerRadius = CornerRadius(w * 0.04f, w * 0.04f)
      )
      // Hard hat brim / visor
      drawRoundRect(
        brush = Brush.horizontalGradient(
          colors = listOf(Color(0xFFEAB308), Color(0xFFFACC15), Color(0xFFCA8A04))
        ),
        topLeft = Offset(domeLeft - w * 0.05f, h * 0.39f),
        size = Size((domeRight - domeLeft) + w * 0.12f, h * 0.075f),
        cornerRadius = CornerRadius(w * 0.04f, w * 0.04f)
      )

      // 6. Top Specular Glass Sheen across badge
      drawRoundRect(
        brush = Brush.verticalGradient(
          colors = listOf(
            Color.White.copy(alpha = 0.28f),
            Color.White.copy(alpha = 0.0f)
          ),
          startY = 0f,
          endY = h * 0.45f
        ),
        topLeft = Offset(w * 0.04f, h * 0.03f),
        size = Size(w * 0.92f, h * 0.40f),
        cornerRadius = CornerRadius(w * 0.22f, w * 0.22f)
      )
    }
  }
}

@Composable
fun StartupLoginScreen(
  isDarkMode: Boolean = currentGlassPalette().isDark,
  onAttemptLogin: (String, String) -> LoginValidationResult = { _, _ -> LoginValidationResult.NO_ACCOUNT_FOUND },
  onFirebaseLoginSuccess: (email: String, displayName: String, password: String) -> Unit = { _, _, _ -> },
  onCheckUsernameRegistered: (String) -> Boolean = { false },
  onCompleteSignUp: (email: String, password: String, displayName: String, recoveryPin: String) -> Unit = { _, _, _, _ -> },
  onVerifyRecoveryPin: (username: String, pin: String) -> Boolean = { _, _ -> false },
  onResetPasswordWithPin: (username: String, pin: String, newPassword: String) -> Boolean = { _, _, _ -> false },
  onContinueAsGuest: () -> Unit,
  modifier: Modifier = Modifier
) {
  val context = LocalContext.current
  val metrics = rememberResponsiveMetrics()

  // Mode toggle: false = "Sign In", true = "Sign Up"
  var isSignUpMode by rememberSaveable { mutableStateOf(false) }
  var fullName by rememberSaveable { mutableStateOf("") }
  var email by rememberSaveable { mutableStateOf("") }
  var password by rememberSaveable { mutableStateOf("") }
  var isPasswordVisible by rememberSaveable { mutableStateOf(false) }
  var isLoading by remember { mutableStateOf(false) }
  var loginErrorMessage by rememberSaveable { mutableStateOf<String?>(null) }
  var loginSuccessMessage by rememberSaveable { mutableStateOf<String?>(null) }

  // Focus states for elevated glass input capsules
  var isFullNameFocused by remember { mutableStateOf(false) }
  var isEmailFocused by remember { mutableStateOf(false) }
  var isPasswordFocused by remember { mutableStateOf(false) }

  // Primary button press-scale animation
  val primaryButtonInteraction = remember { MutableInteractionSource() }
  val isPrimaryPressed by primaryButtonInteraction.collectIsPressedAsState()
  val pressScale by animateFloatAsState(
    targetValue = if (isPrimaryPressed && !isLoading) 0.96f else 1.0f,
    animationSpec = spring(
      dampingRatio = Spring.DampingRatioMediumBouncy,
      stiffness = Spring.StiffnessMediumLow
    ),
    label = "loginPrimaryPressScale"
  )

  fun handlePrimaryAuthAction() {
    if (isLoading) return
    val trimmedEmail = email.trim()

    if (!isSignUpMode) {
      if (trimmedEmail.isBlank() || password.isEmpty()) {
        loginSuccessMessage = null
        loginErrorMessage = "Invalid email or password. Please check your credentials."
        return
      }

      isLoading = true
      loginErrorMessage = null
      loginSuccessMessage = null
      try {
        if (FirebaseApp.getApps(context).isEmpty()) {
          FirebaseApp.initializeApp(context)
        }
        ensureFirebaseInitialized(context)
        FirebaseAuth.getInstance()
          .signInWithEmailAndPassword(trimmedEmail, password)
          .addOnSuccessListener { it ->
            isLoading = false
            val firebaseUser = it.user ?: FirebaseAuth.getInstance().currentUser
            val resolvedEmail = firebaseUser?.email?.trim().orEmpty().ifBlank { trimmedEmail }
            val resolvedDisplayName = firebaseUser?.displayName?.trim().orEmpty()
              .ifBlank { fullName.trim() }
              .ifBlank { resolvedEmail.substringBefore("@").ifBlank { resolvedEmail } }
            loginErrorMessage = null
            loginSuccessMessage = null
            onFirebaseLoginSuccess(resolvedEmail, resolvedDisplayName, password)
          }
          .addOnFailureListener { e ->
            isLoading = false
            loginErrorMessage = mapFirebaseAuthExceptionToMessage(e, isSignUp = false)
          }
      } catch (e: Throwable) {
        isLoading = false
        loginErrorMessage = mapFirebaseAuthExceptionToMessage(e, isSignUp = false)
      }
    } else {
      val trimmedFullName = fullName.trim()
      if (trimmedFullName.isBlank()) {
        loginSuccessMessage = null
        loginErrorMessage = "Registration failed: Please enter your Full Name / Nickname."
        return
      }
      if (trimmedEmail.isBlank()) {
        loginSuccessMessage = null
        loginErrorMessage = "Please enter a valid email address."
        return
      }
      if (password.length < 6) {
        loginSuccessMessage = null
        loginErrorMessage = "Password must be at least 6 characters."
        return
      }

      isLoading = true
      loginErrorMessage = null
      loginSuccessMessage = null
      try {
        if (FirebaseApp.getApps(context).isEmpty()) {
          FirebaseApp.initializeApp(context)
        }
        ensureFirebaseInitialized(context)
        FirebaseAuth.getInstance()
          .createUserWithEmailAndPassword(trimmedEmail, password)
          .addOnSuccessListener { it ->
            val profileUpdate = UserProfileChangeRequest.Builder()
              .setDisplayName(trimmedFullName)
              .build()
            it.user?.updateProfile(profileUpdate)
            val resolvedEmail = it.user?.email?.trim().orEmpty().ifBlank { trimmedEmail }
            isLoading = false
            loginErrorMessage = null
            loginSuccessMessage = null
            Toast.makeText(context, "Account created successfully!", Toast.LENGTH_SHORT).show()
            onCompleteSignUp(resolvedEmail, password, trimmedFullName, "")
          }
          .addOnFailureListener { e ->
            isLoading = false
            loginSuccessMessage = null
            loginErrorMessage = when (e) {
              is FirebaseAuthUserCollisionException -> "An account with this email already exists."
              is FirebaseAuthWeakPasswordException -> "Password must be at least 6 characters."
              is FirebaseAuthInvalidCredentialsException -> "Please enter a valid email address."
              else -> "Registration failed: ${e.localizedMessage}"
            }
          }
      } catch (e: Throwable) {
        isLoading = false
        loginSuccessMessage = null
        loginErrorMessage = when (e) {
          is FirebaseAuthUserCollisionException -> "An account with this email already exists."
          is FirebaseAuthWeakPasswordException -> "Password must be at least 6 characters."
          is FirebaseAuthInvalidCredentialsException -> "Please enter a valid email address."
          else -> "Registration failed: ${e.localizedMessage}"
        }
      }
    }
  }

  // Adaptive High-Visibility Frosted Glass Tokens for Light Mode (!isDarkMode) & Dark Mode (isDarkMode)
  val backgroundBrush = if (isDarkMode) {
    Brush.verticalGradient(
      colors = listOf(Color(0xFF070B14), Color(0xFF070B14))
    )
  } else {
    Brush.verticalGradient(
      colors = listOf(Color(0xFFE2E8F0), Color(0xFFF1F5F9))
    )
  }

  val glassCardShape = RoundedCornerShape(26.dp)
  val glassCardBackgroundBrush = if (isDarkMode) {
    Brush.verticalGradient(
      colors = listOf(
        Color.White.copy(alpha = 0.08f),
        Color.White.copy(alpha = 0.05f)
      )
    )
  } else {
    Brush.verticalGradient(
      colors = listOf(
        Color.White.copy(alpha = 0.72f),
        Color.White.copy(alpha = 0.48f)
      )
    )
  }

  val glassCardBorderStroke = if (isDarkMode) {
    BorderStroke(
      width = 1.dp,
      brush = Brush.linearGradient(
        colors = listOf(
          Color.White.copy(alpha = 0.20f),
          Color.White.copy(alpha = 0.06f)
        )
      )
    )
  } else {
    BorderStroke(
      width = 1.5.dp,
      brush = Brush.linearGradient(
        colors = listOf(
          Color.White.copy(alpha = 0.95f),
          Color(0xFF94A3B8).copy(alpha = 0.35f)
        )
      )
    )
  }

  val titleTextColor = if (isDarkMode) Color.White else Color(0xFF0F172A)
  val subtitleTextColor = if (isDarkMode) Color(0xFF94A3B8) else Color(0xFF475569)

  Box(
    modifier = modifier
      .fillMaxSize()
      .background(brush = backgroundBrush)
      .testTag("startup_login_screen"),
    contentAlignment = Alignment.Center
  ) {
    // Atmospheric background orbs drawn behind the frosted glass card so the translucent card has rich color to refract:
    // - Light Mode (!isDarkMode): Sky-cyan orb (Color(0xFF38BDF8).copy(alpha = 0.35f)) in upper-right +
    //   soft royal-indigo orb (Color(0xFF6366F1).copy(alpha = 0.25f)) in lower-left.
    // - Dark Mode (isDarkMode): Deep cyan-teal bloom (Color(0xFF0EA5E9).copy(alpha = 0.22f)) in upper-right +
    //   royal-violet bloom (Color(0xFF6366F1).copy(alpha = 0.18f)) in lower-left.
    Canvas(modifier = Modifier.fillMaxSize()) {
      val w = size.width
      val h = size.height

      if (isDarkMode) {
        drawCircle(
          brush = Brush.radialGradient(
            colors = listOf(
              Color(0xFF0EA5E9).copy(alpha = 0.22f),
              Color(0xFF0284C7).copy(alpha = 0.08f),
              Color.Transparent
            ),
            center = Offset(w * 0.74f, h * 0.18f),
            radius = w * 0.85f
          ),
          radius = w * 0.85f,
          center = Offset(w * 0.74f, h * 0.18f)
        )

        drawCircle(
          brush = Brush.radialGradient(
            colors = listOf(
              Color(0xFF6366F1).copy(alpha = 0.18f),
              Color(0xFF4F46E5).copy(alpha = 0.06f),
              Color.Transparent
            ),
            center = Offset(w * 0.18f, h * 0.82f),
            radius = w * 0.82f
          ),
          radius = w * 0.82f,
          center = Offset(w * 0.18f, h * 0.82f)
        )
      } else {
        drawCircle(
          brush = Brush.radialGradient(
            colors = listOf(
              Color(0xFF38BDF8).copy(alpha = 0.35f),
              Color(0xFF0284C7).copy(alpha = 0.12f),
              Color.Transparent
            ),
            center = Offset(w * 0.78f, h * 0.20f),
            radius = w * 0.80f
          ),
          radius = w * 0.80f,
          center = Offset(w * 0.78f, h * 0.20f)
        )

        drawCircle(
          brush = Brush.radialGradient(
            colors = listOf(
              Color(0xFF6366F1).copy(alpha = 0.25f),
              Color(0xFF4F46E5).copy(alpha = 0.08f),
              Color.Transparent
            ),
            center = Offset(w * 0.18f, h * 0.80f),
            radius = w * 0.78f
          ),
          radius = w * 0.78f,
          center = Offset(w * 0.18f, h * 0.80f)
        )
      }
    }

    Column(
      modifier = Modifier
        .fillMaxWidth()
        .widthIn(max = 440.dp)
        .windowInsetsPadding(WindowInsets.safeDrawing)
        .imePadding()
        .verticalScroll(rememberScrollState())
        .padding(horizontal = 20.dp, vertical = 18.dp),
      horizontalAlignment = Alignment.CenterHorizontally,
      verticalArrangement = Arrangement.spacedBy(18.dp)
    ) {
      // 1. Clean Emblem Header: Custom SibilCeAppIconBadge() paired with "Sibil CE" and "Civil Engineering Board Companion"
      Row(
        modifier = Modifier
          .fillMaxWidth()
          .padding(horizontal = 4.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(14.dp)
      ) {
        SibilCeAppIconBadge()

        Column(
          modifier = Modifier.weight(1f),
          verticalArrangement = Arrangement.spacedBy(3.dp)
        ) {
          Text(
            text = "Sibil CE",
            style = MaterialTheme.typography.headlineMedium.copy(
              fontSize = 27.sp,
              lineHeight = 32.sp,
              fontWeight = FontWeight.ExtraBold,
              letterSpacing = (-0.4).sp
            ),
            color = titleTextColor,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.testTag("login_app_title")
          )

          Text(
            text = "Civil Engineering Board Companion",
            style = MaterialTheme.typography.bodyMedium.copy(
              fontSize = 13.5.sp,
              fontWeight = FontWeight.SemiBold,
              letterSpacing = 0.1.sp
            ),
            color = subtitleTextColor,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.testTag("login_app_slogan")
          )
        }
      }

      // 2. Main Translucent Frosted Glass Card
      Box(
        modifier = Modifier
          .fillMaxWidth()
          .shadow(
            elevation = if (isDarkMode) 24.dp else 18.dp,
            shape = glassCardShape,
            ambientColor = if (isDarkMode) {
              Color(0xFF0EA5E9).copy(alpha = 0.18f)
            } else {
              Color(0xFF0284C7).copy(alpha = 0.22f)
            },
            spotColor = if (isDarkMode) {
              Color(0xFF2563EB).copy(alpha = 0.24f)
            } else {
              Color(0xFF334155).copy(alpha = 0.20f)
            }
          )
          .clip(glassCardShape)
          .background(brush = glassCardBackgroundBrush)
          .border(border = glassCardBorderStroke, shape = glassCardShape)
      ) {
        Column(
          modifier = Modifier
            .fillMaxWidth()
            .padding(
              horizontal = metrics.scaledDp(20),
              vertical = metrics.scaledDp(22)
            ),
          horizontalAlignment = Alignment.CenterHorizontally,
          verticalArrangement = Arrangement.spacedBy(metrics.scaledDp(14))
        ) {
          // Interactive Mode Pill Switcher (Sign In | Sign Up)
          val pillTrackFill = if (isDarkMode) {
            Color(0xFF0F172A).copy(alpha = 0.72f)
          } else {
            Color(0xFFE2E8F0).copy(alpha = 0.78f)
          }
          val pillTrackBorder = if (isDarkMode) {
            Brush.linearGradient(
              listOf(
                Color.White.copy(alpha = 0.20f),
                Color.White.copy(alpha = 0.05f)
              )
            )
          } else {
            Brush.linearGradient(
              listOf(
                Color.White.copy(alpha = 0.90f),
                Color(0xFFCBD5E1).copy(alpha = 0.75f)
              )
            )
          }
          val inactiveTabTextColor = if (isDarkMode) Color(0xFF94A3B8) else Color(0xFF475569)

          BoxWithConstraints(
            modifier = Modifier
              .fillMaxWidth()
              .height(48.dp)
              .clip(CircleShape)
              .background(pillTrackFill)
              .border(
                width = 1.dp,
                brush = pillTrackBorder,
                shape = CircleShape
              )
              .padding(4.dp)
          ) {
            val segmentWidth = maxWidth / 2f
            val indicatorOffset by animateDpAsState(
              targetValue = if (isSignUpMode) segmentWidth else 0.dp,
              animationSpec = spring(
                dampingRatio = Spring.DampingRatioNoBouncy,
                stiffness = Spring.StiffnessMediumLow
              ),
              label = "authSegmentSlideOffset"
            )

            Box(
              modifier = Modifier
                .offset(x = indicatorOffset)
                .width(segmentWidth)
                .fillMaxHeight()
                .shadow(
                  elevation = 8.dp,
                  shape = CircleShape,
                  ambientColor = Color(0xFF38BDF8).copy(alpha = 0.40f),
                  spotColor = Color(0xFF0284C7).copy(alpha = 0.45f)
                )
                .clip(CircleShape)
                .background(
                  brush = Brush.horizontalGradient(
                    colors = listOf(Color(0xFF0284C7), Color(0xFF38BDF8))
                  )
                )
                .border(
                  width = 1.dp,
                  color = Color.White.copy(alpha = 0.55f),
                  shape = CircleShape
                )
            )

            Row(modifier = Modifier.fillMaxSize()) {
              Box(
                modifier = Modifier
                  .weight(1f)
                  .fillMaxHeight()
                  .clip(CircleShape)
                  .clickable(enabled = !isLoading) {
                    isSignUpMode = false
                    loginErrorMessage = null
                  }
                  .testTag("auth_mode_login_tab"),
                contentAlignment = Alignment.Center
              ) {
                Text(
                  text = "Sign In",
                  style = MaterialTheme.typography.titleSmall.copy(
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                  ),
                  color = if (!isSignUpMode) Color.White else inactiveTabTextColor
                )
              }

              Box(
                modifier = Modifier
                  .weight(1f)
                  .fillMaxHeight()
                  .clip(CircleShape)
                  .clickable(enabled = !isLoading) {
                    isSignUpMode = true
                    loginErrorMessage = null
                    loginSuccessMessage = null
                  }
                  .testTag("sign_up_button"),
                contentAlignment = Alignment.Center
              ) {
                Text(
                  text = "Sign Up",
                  style = MaterialTheme.typography.titleSmall.copy(
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold
                  ),
                  color = if (isSignUpMode) Color.White else inactiveTabTextColor
                )
              }
            }
          }

          // Prominent Frosted Glass Success Message
          loginSuccessMessage?.let { successText ->
            Surface(
              shape = RoundedCornerShape(14.dp),
              color = Color(0xFF10B981).copy(alpha = if (isDarkMode) 0.16f else 0.14f),
              border = BorderStroke(1.dp, Color(0xFF10B981).copy(alpha = 0.50f)),
              modifier = Modifier.fillMaxWidth()
            ) {
              Text(
                text = successText,
                style = MaterialTheme.typography.bodyMedium.copy(
                  fontSize = 13.sp,
                  fontWeight = FontWeight.Bold
                ),
                color = if (isDarkMode) Color(0xFF6EE7B7) else Color(0xFF047857),
                textAlign = TextAlign.Center,
                modifier = Modifier
                  .fillMaxWidth()
                  .padding(horizontal = 12.dp, vertical = 10.dp)
                  .testTag("login_success_text")
              )
            }
          }

          // Sign Up Field 1: Full Name / Nickname
          AnimatedVisibility(
            visible = isSignUpMode,
            enter = expandVertically() + fadeIn(),
            exit = shrinkVertically() + fadeOut()
          ) {
            GlassElevatedInputCapsule(
              value = fullName,
              onValueChange = {
                fullName = it
                if (loginErrorMessage != null) loginErrorMessage = null
              },
              label = "Full Name / Nickname",
              placeholder = "Engr. Juan Dela Cruz",
              leadingIcon = Icons.Default.Badge,
              isFocused = isFullNameFocused,
              onFocusChange = { isFullNameFocused = it },
              isDarkMode = isDarkMode,
              keyboardOptions = KeyboardOptions(
                capitalization = KeyboardCapitalization.Words,
                keyboardType = KeyboardType.Text,
                imeAction = ImeAction.Next
              ),
              metrics = metrics,
              modifier = Modifier
                .fillMaxWidth()
                .testTag("signup_full_name_input")
            )
          }

          // Frosted Glass Email Address Field
          GlassElevatedInputCapsule(
            value = email,
            onValueChange = {
              email = it
              if (loginErrorMessage != null) loginErrorMessage = null
            },
            label = "Email Address",
            placeholder = "scholar@university.edu",
            leadingIcon = Icons.Default.Email,
            isFocused = isEmailFocused,
            onFocusChange = { isEmailFocused = it },
            isDarkMode = isDarkMode,
            keyboardOptions = KeyboardOptions(
              capitalization = KeyboardCapitalization.None,
              autoCorrectEnabled = false,
              keyboardType = KeyboardType.Email,
              imeAction = ImeAction.Next
            ),
            metrics = metrics,
            modifier = Modifier
              .fillMaxWidth()
              .testTag("login_username_input")
          )

          // Frosted Glass Password Field
          GlassElevatedInputCapsule(
            value = password,
            onValueChange = {
              password = it
              if (loginErrorMessage != null) loginErrorMessage = null
            },
            label = "Password",
            placeholder = if (isSignUpMode) "At least 6 characters" else "Enter your password",
            leadingIcon = Icons.Default.Lock,
            isFocused = isPasswordFocused,
            onFocusChange = { isPasswordFocused = it },
            isDarkMode = isDarkMode,
            isPassword = true,
            isPasswordVisible = isPasswordVisible,
            onTogglePasswordVisibility = { isPasswordVisible = !isPasswordVisible },
            keyboardOptions = KeyboardOptions(
              capitalization = KeyboardCapitalization.None,
              keyboardType = KeyboardType.Password,
              imeAction = ImeAction.Done
            ),
            keyboardActions = KeyboardActions(
              onDone = { handlePrimaryAuthAction() }
            ),
            metrics = metrics,
            modifier = Modifier
              .fillMaxWidth()
              .testTag("login_password_input")
          )

          // Red Frosted Glass Error Badge
          loginErrorMessage?.let { errorText ->
            Surface(
              shape = RoundedCornerShape(14.dp),
              color = Color(0xFFEF4444).copy(alpha = if (isDarkMode) 0.16f else 0.12f),
              border = BorderStroke(1.dp, Color(0xFFEF4444).copy(alpha = 0.50f)),
              modifier = Modifier.fillMaxWidth()
            ) {
              Text(
                text = errorText,
                style = MaterialTheme.typography.bodyMedium.copy(
                  fontSize = 13.sp,
                  fontWeight = FontWeight.Bold
                ),
                color = if (isDarkMode) Color(0xFFFCA5A5) else Color(0xFFB91C1C),
                textAlign = TextAlign.Center,
                modifier = Modifier
                  .fillMaxWidth()
                  .padding(horizontal = 12.dp, vertical = 9.dp)
                  .testTag("login_error_text")
              )
            }
          }

          Spacer(modifier = Modifier.height(2.dp))

          // Primary Action Pill Button ("Sign In" / "Create Account")
          val primaryPillShape = RoundedCornerShape(50)
          val buttonBrush = if (isLoading) {
            Brush.horizontalGradient(
              colors = listOf(
                Color(0xFF0284C7).copy(alpha = 0.65f),
                Color(0xFF2563EB).copy(alpha = 0.65f)
              )
            )
          } else {
            Brush.horizontalGradient(
              colors = listOf(Color(0xFF0284C7), Color(0xFF2563EB))
            )
          }

          Box(
            modifier = Modifier
              .fillMaxWidth()
              .height(metrics.scaledDp(52))
              .graphicsLayer {
                scaleX = pressScale
                scaleY = pressScale
              }
              .shadow(
                elevation = if (isLoading) 4.dp else 14.dp,
                shape = primaryPillShape,
                ambientColor = Color(0xFF0284C7).copy(alpha = 0.45f),
                spotColor = Color(0xFF2563EB).copy(alpha = 0.45f)
              )
              .clip(primaryPillShape)
              .background(brush = buttonBrush)
              .border(
                width = 1.dp,
                brush = Brush.verticalGradient(
                  listOf(
                    Color.White.copy(alpha = 0.55f),
                    Color.White.copy(alpha = 0.10f)
                  )
                ),
                shape = primaryPillShape
              )
              .clickable(
                enabled = !isLoading,
                interactionSource = primaryButtonInteraction,
                indication = null,
                onClick = { handlePrimaryAuthAction() }
              )
              .testTag("login_submit_button"),
            contentAlignment = Alignment.Center
          ) {
            Row(
              verticalAlignment = Alignment.CenterVertically,
              horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
              if (isLoading) {
                CircularProgressIndicator(
                  color = Color.White,
                  strokeWidth = 2.2.dp,
                  modifier = Modifier.size(18.dp)
                )
              }
              Text(
                text = if (isSignUpMode) "Create Account" else "Sign In",
                style = MaterialTheme.typography.titleMedium.copy(
                  fontSize = 15.5.sp,
                  fontWeight = FontWeight.ExtraBold
                ),
                color = Color.White,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
              )
              if (!isLoading) {
                Icon(
                  imageVector = Icons.Filled.ArrowForward,
                  contentDescription = null,
                  tint = Color.White,
                  modifier = Modifier.size(18.dp)
                )
              }
            }
          }
        }
      }

      // 3. Sleek Translucent Frosted Glass Pill for "Continue as Offline Scholar →" directly below the main Auth card
      val guestPillFill = if (isDarkMode) {
        Color.White.copy(alpha = 0.06f)
      } else {
        Color.White.copy(alpha = 0.66f)
      }
      val guestPillBorder = if (isDarkMode) {
        BorderStroke(
          width = 1.dp,
          brush = Brush.linearGradient(
            listOf(
              Color.White.copy(alpha = 0.22f),
              Color.White.copy(alpha = 0.06f)
            )
          )
        )
      } else {
        BorderStroke(
          width = 1.5.dp,
          brush = Brush.linearGradient(
            listOf(
              Color.White.copy(alpha = 0.95f),
              Color(0xFF94A3B8).copy(alpha = 0.35f)
            )
          )
        )
      }
      val guestPillTextColor = if (isDarkMode) Color(0xFFE2E8F0) else Color(0xFF0F172A)

      Surface(
        onClick = {
          if (!isLoading) {
            loginErrorMessage = null
            loginSuccessMessage = null
            onContinueAsGuest()
          }
        },
        enabled = !isLoading,
        shape = RoundedCornerShape(50),
        color = guestPillFill,
        shadowElevation = if (isDarkMode) 0.dp else 6.dp,
        border = guestPillBorder,
        modifier = Modifier
          .fillMaxWidth()
          .height(metrics.scaledDp(48))
          .testTag("continue_as_guest_button")
      ) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center
        ) {
          Text(
            text = "Continue as Offline Scholar →",
            style = MaterialTheme.typography.titleSmall.copy(
              fontSize = 13.5.sp,
              fontWeight = FontWeight.SemiBold
            ),
            color = guestPillTextColor,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
          )
        }
      }
    }
  }
}

/**
 * Local Password Recovery Modal triggered by `"Forgot Password?"` on the Login tab:
 * - Prompts for Username and 4-Digit Recovery PIN.
 * - Verifies `hashSecret(enteredPin) == storedPinHash`.
 * - Allows entering and confirming a new password, updating `auth_password_hash` without wiping flashcards or settings.
 */
@Composable
private fun ForgotPasswordRecoveryModal(
  initialUsername: String,
  onCheckUsernameRegistered: (String) -> Boolean,
  onVerifyRecoveryPin: (String, String) -> Boolean,
  onResetPasswordWithPin: (String, String, String) -> Boolean,
  onDismiss: () -> Unit,
  onPasswordResetSuccess: (String) -> Unit
) {
  val palette = currentGlassPalette()
  val metrics = rememberResponsiveMetrics()

  var recoveryUsername by rememberSaveable { mutableStateOf(initialUsername.trim()) }
  var recoveryPin by rememberSaveable { mutableStateOf("") }
  var newPassword by rememberSaveable { mutableStateOf("") }
  var confirmPassword by rememberSaveable { mutableStateOf("") }
  var isPinVerified by rememberSaveable { mutableStateOf(false) }
  var isPinVisible by rememberSaveable { mutableStateOf(false) }
  var isNewPasswordVisible by rememberSaveable { mutableStateOf(false) }
  var isConfirmPasswordVisible by rememberSaveable { mutableStateOf(false) }
  var modalError by rememberSaveable { mutableStateOf<String?>(null) }

  var isUserFocused by remember { mutableStateOf(false) }
  var isPinFocused by remember { mutableStateOf(false) }
  var isNewPassFocused by remember { mutableStateOf(false) }
  var isConfirmPassFocused by remember { mutableStateOf(false) }

  val cardShape = RoundedCornerShape(28.dp)

  Dialog(
    onDismissRequest = onDismiss,
    properties = DialogProperties(usePlatformDefaultWidth = false)
  ) {
    Box(
      modifier = Modifier
        .fillMaxWidth(0.92f)
        .widthIn(max = if (metrics.screenWidthDp > 600) 480.dp else 420.dp)
        .shadow(
          elevation = 24.dp,
          shape = cardShape,
          ambientColor = Color(0xFF6366F1).copy(alpha = 0.40f),
          spotColor = Color(0xFF8B5CF6).copy(alpha = 0.40f)
        )
        .clip(cardShape)
        .background(palette.cardSurface.copy(alpha = 0.96f))
        .border(
          width = 1.dp,
          brush = Brush.linearGradient(
            colors = listOf(
              Color.White.copy(alpha = 0.45f),
              Color.White.copy(alpha = 0.08f)
            )
          ),
          shape = cardShape
        )
        .testTag("forgot_password_recovery_modal")
    ) {
      Column(
        modifier = Modifier
          .fillMaxWidth()
          .verticalScroll(rememberScrollState())
          .padding(horizontal = 22.dp, vertical = 22.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
      ) {
        Row(
          modifier = Modifier.fillMaxWidth(),
          horizontalArrangement = Arrangement.SpaceBetween,
          verticalAlignment = Alignment.CenterVertically
        ) {
          Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(2.dp)
          ) {
            Text(
              text = "Reset Scholar Password",
              style = MaterialTheme.typography.titleLarge.copy(
                fontSize = 19.sp,
                fontWeight = FontWeight.Bold
              ),
              color = palette.textPrimary
            )
            Text(
              text = "4-DIGIT RECOVERY PIN VERIFICATION",
              style = MaterialTheme.typography.labelSmall.copy(
                fontSize = 10.sp,
                fontWeight = FontWeight.Bold,
                letterSpacing = 1.0.sp
              ),
              color = palette.accentIndigo
            )
          }

          IconButton(
            onClick = onDismiss,
            modifier = Modifier
              .size(40.dp)
              .clip(CircleShape)
              .background(palette.nestedCardFill)
              .testTag("close_forgot_password_modal_button")
          ) {
            Icon(
              imageVector = Icons.Default.Close,
              contentDescription = "Close Recovery Modal",
              tint = palette.textPrimary,
              modifier = Modifier.size(18.dp)
            )
          }
        }

        HorizontalDivider(color = palette.dividerColor)

        // Username / Student ID
        GlassElevatedInputCapsule(
          value = recoveryUsername,
          onValueChange = {
            recoveryUsername = it
            isPinVerified = false
            modalError = null
          },
          label = "Username / Student ID",
          placeholder = "Enter your registered username",
          leadingIcon = Icons.Default.Person,
          isFocused = isUserFocused,
          onFocusChange = { isUserFocused = it },
          keyboardOptions = KeyboardOptions(
            keyboardType = KeyboardType.Text,
            imeAction = ImeAction.Next
          ),
          metrics = metrics,
          modifier = Modifier
            .fillMaxWidth()
            .testTag("recovery_username_input")
        )

        // 4-Digit Recovery PIN
        GlassElevatedInputCapsule(
          value = recoveryPin,
          onValueChange = { raw ->
            recoveryPin = raw.filter { it.isDigit() }.take(4)
            isPinVerified = false
            modalError = null
          },
          label = "4-Digit Recovery PIN",
          placeholder = "Enter your 4-digit PIN",
          leadingIcon = Icons.Default.Key,
          isFocused = isPinFocused,
          onFocusChange = { isPinFocused = it },
          isPassword = true,
          isPasswordVisible = isPinVisible,
          onTogglePasswordVisibility = { isPinVisible = !isPinVisible },
          keyboardOptions = KeyboardOptions(
            keyboardType = KeyboardType.NumberPassword,
            imeAction = if (isPinVerified) ImeAction.Next else ImeAction.Done
          ),
          metrics = metrics,
          modifier = Modifier
            .fillMaxWidth()
            .testTag("recovery_pin_input")
        )

        AnimatedVisibility(
          visible = isPinVerified,
          enter = expandVertically() + fadeIn(),
          exit = shrinkVertically() + fadeOut()
        ) {
          Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(12.dp)
          ) {
            GlassElevatedInputCapsule(
              value = newPassword,
              onValueChange = {
                newPassword = it
                modalError = null
              },
              label = "New Password",
              placeholder = "Enter new password",
              leadingIcon = Icons.Default.Lock,
              isFocused = isNewPassFocused,
              onFocusChange = { isNewPassFocused = it },
              isPassword = true,
              isPasswordVisible = isNewPasswordVisible,
              onTogglePasswordVisibility = { isNewPasswordVisible = !isNewPasswordVisible },
              keyboardOptions = KeyboardOptions(
                keyboardType = KeyboardType.Password,
                imeAction = ImeAction.Next
              ),
              metrics = metrics,
              modifier = Modifier
                .fillMaxWidth()
                .testTag("recovery_new_password_input")
            )

            GlassElevatedInputCapsule(
              value = confirmPassword,
              onValueChange = {
                confirmPassword = it
                modalError = null
              },
              label = "Confirm New Password",
              placeholder = "Re-enter new password",
              leadingIcon = Icons.Default.Lock,
              isFocused = isConfirmPassFocused,
              onFocusChange = { isConfirmPassFocused = it },
              isPassword = true,
              isPasswordVisible = isConfirmPasswordVisible,
              onTogglePasswordVisibility = { isConfirmPasswordVisible = !isConfirmPasswordVisible },
              keyboardOptions = KeyboardOptions(
                keyboardType = KeyboardType.Password,
                imeAction = ImeAction.Done
              ),
              metrics = metrics,
              modifier = Modifier
                .fillMaxWidth()
                .testTag("recovery_confirm_password_input")
            )
          }
        }

        modalError?.let { err ->
          Surface(
            shape = RoundedCornerShape(12.dp),
            color = Color(0xFFEF4444).copy(alpha = 0.14f),
            border = BorderStroke(1.dp, Color(0xFFEF4444).copy(alpha = 0.45f)),
            modifier = Modifier.fillMaxWidth()
          ) {
            Text(
              text = err,
              style = MaterialTheme.typography.bodySmall.copy(
                fontSize = 12.5.sp,
                fontWeight = FontWeight.Bold
              ),
              color = if (palette.isDark) Color(0xFFFCA5A5) else Color(0xFFD32F2F),
              textAlign = TextAlign.Center,
              modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 12.dp, vertical = 8.dp)
                .testTag("recovery_error_text")
            )
          }
        }

        // Action Button: Verify PIN -> Update Password
        Box(
          modifier = Modifier
            .fillMaxWidth()
            .height(50.dp)
            .shadow(
              elevation = 10.dp,
              shape = RoundedCornerShape(14.dp),
              ambientColor = Color(0xFF6366F1).copy(alpha = 0.4f),
              spotColor = Color(0xFF8B5CF6).copy(alpha = 0.4f)
            )
            .clip(RoundedCornerShape(14.dp))
            .background(
              Brush.horizontalGradient(
                listOf(Color(0xFF6366F1), Color(0xFF8B5CF6))
              )
            )
            .clickable {
              val cleanUser = recoveryUsername.trim()
              val cleanPin = recoveryPin.trim()
              if (cleanUser.isBlank()) {
                modalError = "Please enter your Username / Student ID"
                return@clickable
              }
              if (!onCheckUsernameRegistered(cleanUser)) {
                modalError = "No scholar account found for that username"
                return@clickable
              }
              if (cleanPin.length != 4) {
                modalError = "Please enter your 4-digit Recovery PIN"
                return@clickable
              }
              if (!onVerifyRecoveryPin(cleanUser, cleanPin)) {
                modalError = "Invalid 4-Digit Recovery PIN"
                return@clickable
              }
              if (!isPinVerified) {
                isPinVerified = true
                modalError = null
              } else {
                if (newPassword.isBlank()) {
                  modalError = "Please enter a new password"
                  return@clickable
                }
                if (newPassword != confirmPassword) {
                  modalError = "Passwords do not match"
                  return@clickable
                }
                val updated = onResetPasswordWithPin(cleanUser, cleanPin, newPassword)
                if (updated) {
                  modalError = null
                  onPasswordResetSuccess(cleanUser)
                } else {
                  modalError = "Unable to update password. Please verify your PIN."
                }
              }
            }
            .testTag("recovery_submit_button"),
          contentAlignment = Alignment.Center
        ) {
          Text(
            text = if (isPinVerified) "Update Password" else "Verify Recovery PIN",
            style = MaterialTheme.typography.titleMedium.copy(
              fontSize = 15.sp,
              fontWeight = FontWeight.ExtraBold
            ),
            color = Color.White
          )
        }
      }
    }
  }
}

@Composable
private fun GlassElevatedInputCapsule(
  value: String,
  onValueChange: (String) -> Unit,
  label: String,
  placeholder: String,
  leadingIcon: ImageVector,
  isFocused: Boolean,
  onFocusChange: (Boolean) -> Unit,
  metrics: ResponsiveMetrics,
  modifier: Modifier = Modifier,
  isDarkMode: Boolean = currentGlassPalette().isDark,
  isPassword: Boolean = false,
  isPasswordVisible: Boolean = false,
  onTogglePasswordVisibility: (() -> Unit)? = null,
  keyboardOptions: KeyboardOptions = KeyboardOptions.Default,
  keyboardActions: KeyboardActions = KeyboardActions.Default
) {
  val focusGlowColor = if (isDarkMode) Color(0xFF38BDF8) else Color(0xFF0284C7)
  val leadingIconColor = if (isDarkMode) Color(0xFF38BDF8) else Color(0xFF0284C7)
  val capsuleFillColor = if (isDarkMode) {
    Color(0xFF0F172A).copy(alpha = if (isFocused) 0.80f else 0.65f)
  } else {
    Color(0xFFF8FAFC).copy(alpha = if (isFocused) 0.90f else 0.75f)
  }
  val capsuleBorderColor = when {
    isFocused -> focusGlowColor
    isDarkMode -> Color.White.copy(alpha = 0.12f)
    else -> Color(0xFFCBD5E1)
  }
  val inputTextColor = if (isDarkMode) Color.White else Color(0xFF0F172A)
  val unfocusedLabelColor = if (isDarkMode) Color(0xFF94A3B8) else Color(0xFF475569)
  val placeholderTextColor = if (isDarkMode) {
    Color(0xFF94A3B8).copy(alpha = 0.70f)
  } else {
    Color(0xFF64748B).copy(alpha = 0.78f)
  }
  val capsuleShape = RoundedCornerShape(16.dp)

  Box(
    modifier = modifier
      .shadow(
        elevation = if (isFocused) 10.dp else 3.dp,
        shape = capsuleShape,
        ambientColor = if (isFocused) {
          focusGlowColor.copy(alpha = 0.35f)
        } else if (isDarkMode) {
          Color.Black.copy(alpha = 0.35f)
        } else {
          Color(0xFF64748B).copy(alpha = 0.18f)
        },
        spotColor = if (isFocused) {
          focusGlowColor.copy(alpha = 0.35f)
        } else if (isDarkMode) {
          Color.Black.copy(alpha = 0.35f)
        } else {
          Color(0xFF64748B).copy(alpha = 0.18f)
        }
      )
      .clip(capsuleShape)
      .background(color = capsuleFillColor)
      .border(
        width = if (isFocused) 1.4.dp else 1.dp,
        color = capsuleBorderColor,
        shape = capsuleShape
      )
  ) {
    OutlinedTextField(
      value = value,
      onValueChange = onValueChange,
      label = {
        Text(
          text = label,
          style = MaterialTheme.typography.bodySmall.copy(
            fontWeight = FontWeight.SemiBold
          ),
          maxLines = 1,
          overflow = TextOverflow.Ellipsis
        )
      },
      placeholder = {
        Text(
          text = placeholder,
          style = MaterialTheme.typography.bodyMedium,
          color = placeholderTextColor,
          maxLines = 1,
          overflow = TextOverflow.Ellipsis
        )
      },
      leadingIcon = {
        Icon(
          imageVector = leadingIcon,
          contentDescription = null,
          tint = leadingIconColor,
          modifier = Modifier.size(20.dp)
        )
      },
      trailingIcon = if (isPassword && onTogglePasswordVisibility != null) {
        {
          IconButton(
            onClick = onTogglePasswordVisibility,
            modifier = Modifier
              .size(48.dp)
              .minimumInteractiveComponentSize()
              .testTag("toggle_password_visibility_button")
          ) {
            Icon(
              imageVector = if (isPasswordVisible) {
                Icons.Filled.VisibilityOff
              } else {
                Icons.Filled.Visibility
              },
              contentDescription = if (isPasswordVisible) "Hide password" else "Show password",
              tint = if (isFocused) focusGlowColor else unfocusedLabelColor,
              modifier = Modifier.size(20.dp)
            )
          }
        }
      } else null,
      visualTransformation = if (isPassword && !isPasswordVisible) {
        PasswordVisualTransformation()
      } else {
        VisualTransformation.None
      },
      textStyle = MaterialTheme.typography.bodyLarge.copy(
        fontSize = metrics.scaledSp(15),
        color = inputTextColor,
        fontWeight = FontWeight.Medium
      ),
      singleLine = true,
      shape = capsuleShape,
      colors = OutlinedTextFieldDefaults.colors(
        focusedBorderColor = Color.Transparent,
        unfocusedBorderColor = Color.Transparent,
        focusedContainerColor = Color.Transparent,
        unfocusedContainerColor = Color.Transparent,
        focusedLabelColor = focusGlowColor,
        unfocusedLabelColor = unfocusedLabelColor,
        cursorColor = focusGlowColor
      ),
      keyboardOptions = keyboardOptions,
      keyboardActions = keyboardActions,
      modifier = Modifier
        .fillMaxWidth()
        .onFocusChanged { onFocusChange(it.isFocused) }
    )
  }
}

