                Row(
                  modifier = Modifier.fillMaxWidth(),
                  verticalAlignment = Alignment.CenterVertically,
                  horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                  Icon(
                    imageVector = Icons.Outlined.LocationOn,
                    contentDescription = null,
                    tint = palette.accentIndigo,
                    modifier = Modifier.size(14.dp)
                  )
                  Text(
                    text = item.room,
                    style = MaterialTheme.typography.labelSmall.copy(
                      fontSize = metrics.scaledSp(11),
                      fontWeight = FontWeight.Bold
                    ),
                    color = palette.accentIndigo,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f)
                  )
                }
              }
            }
          }
        }
      }
    }
  }
}

enum class DeadlineUrgencyType {
  OVERDUE,
  TODAY,
  TOMORROW,
  UPCOMING
}

data class DashboardUpcomingItem(
  val id: Int = 0,
  val title: String = "",
  val category: String = DEFAULT_TASK_CATEGORY,
  val dueDateDisplay: String = "",
  val dueDateIso: String = "",
  val priority: Int = 0,
  val hasNotesOrSubtasks: Boolean = false,
  val daysRemaining: Int = 0,
  val urgencyLabel: String = "Upcoming",
  val urgencyType: DeadlineUrgencyType = DeadlineUrgencyType.UPCOMING,
  val isCompleted: Boolean = false,
  val isScheduleItem: Boolean = false,
  val scheduleId: Int? = null
)

fun parseDaysRemainingAndUrgency(dueDate: String): Triple<Int, String, DeadlineUrgencyType> {
  val clean = dueDate.trim()
  if (clean.isEmpty() || clean.equals("Upcoming", ignoreCase = true)) {
    return Triple(3, "In 3 days", DeadlineUrgencyType.UPCOMING)
  }
  if (clean.equals("Overdue", ignoreCase = true) || clean.equals("Yesterday", ignoreCase = true)) {
    return Triple(-1, "Overdue", DeadlineUrgencyType.OVERDUE)
  }
  if (clean.equals("Today", ignoreCase = true)) {
    return Triple(0, "Today", DeadlineUrgencyType.TODAY)
  }
  if (clean.equals("Tomorrow", ignoreCase = true)) {
    return Triple(1, "Tomorrow", DeadlineUrgencyType.TOMORROW)
  }

  val inDaysMatch = Regex("""(?i)(?:in\s+)?(\d+)\s*days?""").find(clean)
  if (inDaysMatch != null) {
    val days = inDaysMatch.groupValues[1].toIntOrNull() ?: 2
    return when {
      days <= 0 -> Triple(0, "Today", DeadlineUrgencyType.TODAY)
      days == 1 -> Triple(1, "Tomorrow", DeadlineUrgencyType.TOMORROW)
      else -> Triple(days, "In $days days", DeadlineUrgencyType.UPCOMING)
    }
  }

  val now = try {
    LocalDate.now()
  } catch (_: Throwable) {
    null
  }

  if (now != null) {
    val currentYear = now.year
    val datePatterns = listOf(
      "yyyy-MM-dd",
      "MM/dd/yyyy",
      "M/d/yyyy",
      "MMM d, yyyy",
      "MMM dd, yyyy",
      "MMMM d, yyyy",
      "dd MMM yyyy",
      "d MMM yyyy",
      "MMM d",
      "MMM dd",
      "MMMM d"
    )

    for (pattern in datePatterns) {
      try {
        val formatter = DateTimeFormatter.ofPattern(pattern, Locale.ENGLISH)
        val targetDate = if (pattern.contains("y")) {
          LocalDate.parse(clean, formatter)
        } else {
          val parsedMonthDay = MonthDay.parse(clean, formatter)
          parsedMonthDay.atYear(currentYear)
        }
        val diff = ChronoUnit.DAYS.between(now, targetDate).toInt()
        return when {
          diff < 0 -> Triple(diff, "Overdue", DeadlineUrgencyType.OVERDUE)
          diff == 0 -> Triple(0, "Today", DeadlineUrgencyType.TODAY)
          diff == 1 -> Triple(1, "Tomorrow", DeadlineUrgencyType.TOMORROW)
          else -> Triple(diff, "In $diff days", DeadlineUrgencyType.UPCOMING)
        }
      } catch (_: Throwable) {
        // try next pattern
      }
    }

    for (dow in DayOfWeek.values()) {
      if (clean.contains(dow.name, ignoreCase = true) ||
        clean.contains(dow.getDisplayName(TextStyle.SHORT, Locale.ENGLISH), ignoreCase = true)
      ) {
        val daysUntil = (dow.value - now.dayOfWeek.value + 7) % 7
        return when {
          daysUntil == 0 -> Triple(0, "Today", DeadlineUrgencyType.TODAY)
          daysUntil == 1 -> Triple(1, "Tomorrow", DeadlineUrgencyType.TOMORROW)
          else -> Triple(daysUntil, "In $daysUntil days", DeadlineUrgencyType.UPCOMING)
        }
      }
    }
  }

  return Triple(4, "In 4 days", DeadlineUrgencyType.UPCOMING)
}

/**
 * Frosted Glass "Upcoming Deadlines" section (`LiquidGlassCard`) with translucent glass tiles,
 * live urgency badges, and empty state with glowing cyan-to-blue "Add Task" button.
 */
@Composable
private fun UpcomingDeadlinesSectionCard(
  upcomingItems: List<DashboardUpcomingItem>,
  metrics: ResponsiveMetrics,
  onToggleComplete: (Int) -> Unit,
  onItemClick: (DashboardUpcomingItem) -> Unit = {},
  onAddTaskClick: () -> Unit = {}
) {
  val palette = currentGlassPalette()
  LiquidGlassCard(
    cornerRadius = 26.dp,
    elevation = 4.dp,
    modifier = Modifier
      .fillMaxWidth()
      .testTag("upcoming_deadlines_section_card")
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        .padding(metrics.scaledDp(20)),
      verticalArrangement = Arrangement.spacedBy(metrics.scaledDp(14))
    ) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically
      ) {
        Text(
          text = stringResource(R.string.upcoming_deadlines_title),
          style = MaterialTheme.typography.titleLarge.copy(
            fontSize = metrics.scaledSp(19),
            fontWeight = FontWeight.Bold
          ),
          color = palette.textPrimary,
          maxLines = 1,
          overflow = TextOverflow.Ellipsis,
          modifier = Modifier
            .weight(1f)
            .testTag("upcoming_deadlines_header")
        )

        Box(
          modifier = Modifier
            .clip(CircleShape)
            .background(Color(0xFF0EA5E9).copy(alpha = 0.16f))
            .border(BorderStroke(1.dp, Color(0xFF38BDF8).copy(alpha = 0.38f)), CircleShape)
        ) {
          Text(
            text = "${upcomingItems.size} Active",
            style = MaterialTheme.typography.labelMedium.copy(
              fontSize = metrics.scaledSp(12),
              fontWeight = FontWeight.Bold
            ),
            color = palette.accentIndigo,
            maxLines = 1,
            modifier = Modifier.padding(
              horizontal = metrics.scaledDp(12),
              vertical = metrics.scaledDp(5)
            )
          )
        }
      }

      if (upcomingItems.isEmpty()) {
        Column(
          modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = metrics.scaledDp(24))
            .testTag("no_upcoming_deadlines_box"),
          horizontalAlignment = Alignment.CenterHorizontally,
          verticalArrangement = Arrangement.spacedBy(metrics.scaledDp(12))
        ) {
          Box(
            modifier = Modifier
              .size(52.dp)
              .clip(CircleShape)
              .background(Color(0xFF0EA5E9).copy(alpha = 0.16f))
              .border(BorderStroke(1.dp, Color(0xFF38BDF8).copy(alpha = 0.38f)), CircleShape),
            contentAlignment = Alignment.Center
          ) {
            Icon(
              imageVector = Icons.Filled.CheckCircle,
              contentDescription = null,
              tint = if (palette.isDark) Color(0xFF38BDF8) else Color(0xFF0284C7),
              modifier = Modifier.size(28.dp)
            )
          }

          Text(
            text = "No upcoming deadlines. All caught up!",
            style = MaterialTheme.typography.bodyLarge.copy(
              fontSize = metrics.scaledSp(15),
              fontWeight = FontWeight.SemiBold
            ),
            color = palette.textSecondary,
            textAlign = TextAlign.Center,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
          )

          Box(
            modifier = Modifier
              .clip(RoundedCornerShape(16.dp))
              .background(
                brush = Brush.horizontalGradient(
                  colors = listOf(
                    Color(0xFF38BDF8),
                    Color(0xFF2563EB)
                  )
                ),
                shape = RoundedCornerShape(16.dp)
              )
              .border(
                BorderStroke(1.dp, Color.White.copy(alpha = 0.55f)),
                RoundedCornerShape(16.dp)
              )
              .clickable(onClick = onAddTaskClick)
              .minimumInteractiveComponentSize()
              .padding(
                horizontal = metrics.scaledDp(20),
                vertical = metrics.scaledDp(10)
              )
              .testTag("upcoming_add_task_button"),
            contentAlignment = Alignment.Center
          ) {
            Row(
              verticalAlignment = Alignment.CenterVertically,
              horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
              Icon(
                imageVector = Icons.Default.Add,
                contentDescription = null,
                tint = Color.White,
                modifier = Modifier.size(18.dp)
              )
              Text(
                text = "Add Task",
                style = MaterialTheme.typography.labelLarge.copy(
                  fontSize = metrics.scaledSp(14),
                  fontWeight = FontWeight.Bold
                ),
                color = Color.White
              )
            }
          }
        }
      } else {
        Column(
          verticalArrangement = Arrangement.spacedBy(metrics.scaledDp(10))
        ) {
          upcomingItems.forEach { item ->
            DashboardUpcomingItemCard(
              item = item,
              metrics = metrics,
              onToggleComplete = { onToggleComplete(item.id) },
              onClick = { onItemClick(item) }
            )
          }
        }
      }
    }
  }
}

/**
 * Backward compatibility overload for UpcomingDeadlinesSectionCard taking activeTasks
 */
@Composable
private fun UpcomingDeadlinesSectionCard(
  activeTasks: List<Task>,
  metrics: ResponsiveMetrics,
  onToggleComplete: (Int) -> Unit
) = UpcomingDeadlinesSectionCard(
  upcomingItems = activeTasks.map { task ->
    val (days, label, urgency) = parseDaysRemainingAndUrgency(task.dueDate)
    DashboardUpcomingItem(
      id = task.id,
      title = task.title,
      category = task.subjectCategory.ifBlank { DEFAULT_TASK_CATEGORY },
      dueDateDisplay = if (task.dueDate.isNotBlank()) task.dueDate else label,
      daysRemaining = days,
      urgencyLabel = label,
      urgencyType = urgency,
      isCompleted = task.isCompleted,
      isScheduleItem = false
    )
  },
  metrics = metrics,
  onToggleComplete = onToggleComplete
)

/**
 * Dynamic translucent glass tile for each upcoming deadline, with urgency badge,
 * interactive completion ring, and fluid responsiveness.
 */
@Composable
private fun DashboardUpcomingItemCard(
  item: DashboardUpcomingItem,
  metrics: ResponsiveMetrics,
  onToggleComplete: () -> Unit,
  onClick: () -> Unit
) {
  val palette = currentGlassPalette()
  val context = LocalContext.current
  val localView = LocalView.current

  val (urgencyBg, urgencyBorder, urgencyTextColor) = when (item.urgencyType) {
    DeadlineUrgencyType.OVERDUE -> Triple(
      Color(0xFFEF4444).copy(alpha = 0.16f),
      Color(0xFFEF4444).copy(alpha = 0.40f),
      Color(0xFFF87171)
    )
    DeadlineUrgencyType.TODAY -> Triple(
      Color(0xFFF59E0B).copy(alpha = 0.18f),
      Color(0xFFF59E0B).copy(alpha = 0.45f),
      Color(0xFFF59E0B)
    )
    DeadlineUrgencyType.TOMORROW -> Triple(
      Color(0xFFEAB308).copy(alpha = 0.16f),
      Color(0xFFEAB308).copy(alpha = 0.38f),
      Color(0xFFFACC15)
    )
    DeadlineUrgencyType.UPCOMING -> Triple(
      LiquidRoyalPeriwinkle.copy(alpha = 0.16f),
      LiquidRoyalPeriwinkle.copy(alpha = 0.35f),
      palette.accentIndigo
    )
  }

  LiquidGlassContainer(
    cornerRadius = 18.dp,
    fillAlpha = 0.75f,
    onClick = {
      playCardHapticSound(context, localView)
      onClick()
    },
    modifier = Modifier
      .fillMaxWidth()
      .testTag("dashboard_deadline_card_${item.id}")
  ) {
    Row(
      modifier = Modifier
        .fillMaxWidth()
        .padding(
          horizontal = metrics.scaledDp(16),
          vertical = metrics.scaledDp(14)
        ),
      verticalAlignment = Alignment.CenterVertically,
      horizontalArrangement = Arrangement.spacedBy(metrics.scaledDp(12))
    ) {
      if (item.isScheduleItem) {
        Surface(
          shape = CircleShape,
          color = LiquidRoyalPeriwinkle.copy(alpha = 0.15f),
          border = BorderStroke(1.dp, LiquidRoyalPeriwinkle.copy(alpha = 0.35f)),
          modifier = Modifier.size(32.dp)
        ) {
          Box(contentAlignment = Alignment.Center) {
            Icon(
              imageVector = Icons.Outlined.Schedule,
              contentDescription = "Class Schedule",
              tint = palette.accentIndigo,
              modifier = Modifier.size(16.dp)
            )
          }
        }
      } else {
        // Priority-colored checkbox + glowing status dot
        val priorityStrokeColor = taskPriorityColor(item.priority, palette.checkboxUncheckedBorder)
        Surface(
          onClick = {
            playCardHapticSound(context, localView)
            onToggleComplete()
          },
          shape = RoundedCornerShape(8.dp),
          color = if (item.priority > 0) priorityStrokeColor.copy(alpha = 0.12f) else palette.checkboxUncheckedFill,
          border = BorderStroke(1.8.dp, priorityStrokeColor),
          modifier = Modifier
            .size(30.dp)
            .minimumInteractiveComponentSize()
        ) {
          Box(contentAlignment = Alignment.Center) {
            Box(
              modifier = Modifier
                .size(8.dp)
                .shadow(4.dp, CircleShape, spotColor = if (item.priority > 0) priorityStrokeColor else LiquidCyanGlow)
                .clip(CircleShape)
                .background(
                  color = if (item.priority > 0) priorityStrokeColor else LiquidCyanGlow
                )
            )
          }
        }
      }

      Column(
        modifier = Modifier.weight(1f),
        verticalArrangement = Arrangement.spacedBy(4.dp)
      ) {
        Text(
          text = item.title,
          style = MaterialTheme.typography.titleMedium.copy(
            fontSize = metrics.scaledSp(15),
            fontWeight = FontWeight.Bold
          ),
          color = palette.textPrimary,
          maxLines = 2,
          overflow = TextOverflow.Ellipsis,
          modifier = Modifier.fillMaxWidth()
        )

        Row(
          modifier = Modifier.fillMaxWidth(),
          verticalAlignment = Alignment.CenterVertically,
          horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
          Icon(
            imageVector = Icons.Outlined.CalendarToday,
            contentDescription = null,
            tint = palette.accentIndigo,
            modifier = Modifier.size(14.dp)
          )
          Text(
            text = "Due ${item.dueDateDisplay}",
            style = MaterialTheme.typography.labelMedium.copy(
              fontSize = metrics.scaledSp(12),
              fontWeight = FontWeight.SemiBold
            ),
            color = palette.textSecondary,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
          )
          Box(
            modifier = Modifier
              .clip(CircleShape)
              .background(LiquidRoyalPeriwinkle.copy(alpha = 0.16f))
              .border(BorderStroke(1.dp, LiquidRoyalPeriwinkle.copy(alpha = 0.35f)), CircleShape)
          ) {
            Text(
              text = item.category.ifBlank { DEFAULT_TASK_CATEGORY },
              style = MaterialTheme.typography.labelSmall.copy(
                fontSize = metrics.scaledSp(10),
                fontWeight = FontWeight.Bold
              ),
              color = palette.accentIndigo,
              maxLines = 1,
              overflow = TextOverflow.Ellipsis,
              modifier = Modifier
                .widthIn(max = 110.dp)
                .padding(horizontal = 8.dp, vertical = 3.dp)
            )
          }
        }
      }

      // Urgency Badge Pill
      Box(
        modifier = Modifier
          .clip(RoundedCornerShape(12.dp))
          .background(urgencyBg)
          .border(BorderStroke(1.dp, urgencyBorder), RoundedCornerShape(12.dp))
          .padding(horizontal = 10.dp, vertical = 5.dp)
      ) {
        Text(
          text = item.urgencyLabel,
          style = MaterialTheme.typography.labelSmall.copy(
            fontSize = metrics.scaledSp(11),
            fontWeight = FontWeight.Bold
          ),
          color = urgencyTextColor,
          maxLines = 1
        )
      }
    }
  }
}

/**
 * Translucent glass tile (`LiquidGlassContainer`) for each active task in Upcoming Deadlines,
 * featuring a subtle glowing status dot and frosted category pill.
 */
@Composable
private fun DashboardTaskMiniCard(
  task: Task,
  metrics: ResponsiveMetrics,
  onToggleComplete: () -> Unit
) {
  val (days, label, urgency) = parseDaysRemainingAndUrgency(task.dueDate)
  val item = DashboardUpcomingItem(
    id = task.id,
    title = task.title,
    category = task.subjectCategory.ifBlank { DEFAULT_TASK_CATEGORY },
    dueDateDisplay = if (task.dueDate.isNotBlank()) task.dueDate else label,
    daysRemaining = days,
    urgencyLabel = label,
    urgencyType = urgency,
    isCompleted = task.isCompleted,
    isScheduleItem = false
  )
  DashboardUpcomingItemCard(
    item = item,
    metrics = metrics,
    onToggleComplete = onToggleComplete,
    onClick = onToggleComplete
  )
}

/**
 * Dedicated Extras Screen (`ExtrasScreen`):
 * Contains the engineering tool cards arranged in a neat 2x2 grid with floating elevation
 * and cream card styling (`#FFFBF0`):
 * - Scientific Calculator
 * - Unit Converter
 * - BOQ Estimator
 * - Smart Flashcards (Active-recall CE decks, PDF/DOCX AI import simulator, & spaced-repetition study mode)
 */
@Composable
fun ExtrasScreen(
  modifier: Modifier = Modifier,
  viewModel: TaskViewModel = viewModel()
) {
  val context = LocalContext.current
  val localView = LocalView.current
  val localStorageManager = remember(context) {
    LocalStorageManager(context.applicationContext)
  }
  LaunchedEffect(localStorageManager) {
    viewModel.attachStorage(localStorageManager)
  }

  val metrics = rememberResponsiveMetrics()
  val palette = currentGlassPalette()
  var isFlashcardsOpen by rememberSaveable { mutableStateOf(false) }
  var isFormulaVaultOpen by rememberSaveable { mutableStateOf(false) }
  var activeStudyDeckId by rememberSaveable { mutableStateOf<Int?>(null) }
  var comingSoonSnackbarMessage by remember { mutableStateOf<String?>(null) }

  LaunchedEffect(comingSoonSnackbarMessage) {
    if (comingSoonSnackbarMessage != null) {
      delay(2600L)
      comingSoonSnackbarMessage = null
    }
  }

  val comingSoonModules = remember {
    listOf(
      ExtraToolItem(
        id = "unit_converter",
        title = "Unit Converter",
        subtitle = "SI & Imperial engineering units",
        icon = Icons.Filled.SwapHoriz
      ),
      ExtraToolItem(
        id = "gpa_calculator",
        title = "GPA Calculator",
        subtitle = "Semester GWA & board weighting",
        icon = Icons.Filled.Calculate
      ),
      ExtraToolItem(
        id = "scientific_calculator",
        title = "Scientific Calculator",
        subtitle = "Beam & matrix solver",
        icon = Icons.Filled.Architecture
      ),
      ExtraToolItem(
        id = "boq_estimator",
        title = "Quick Tools & BOQ",
        subtitle = "Material & cost takeoff",
        icon = Icons.Filled.RequestQuote
      )
    )
  }

  val activeStudyDeck = viewModel.flashcardDecks.firstOrNull { it.id == activeStudyDeckId }

  if (isFormulaVaultOpen) {
    FormulaVaultMainView(
      metrics = metrics,
      onBackToExtras = { isFormulaVaultOpen = false },
      viewModel = viewModel,
      modifier = modifier
    )
    return
  }

  if (isFlashcardsOpen) {
    if (activeStudyDeck != null) {
      FlashcardStudyScreen(
        deck = activeStudyDeck,
        metrics = metrics,
        onRateCard = { cardId, rating ->
          viewModel.updateFlashcardMastery(
            deckId = activeStudyDeck.id,
            cardId = cardId,
            newMasteryLevel = rating
          )
        },
        onResetMastery = {
          viewModel.resetDeckMastery(activeStudyDeck.id)
        },
        onBackToDecks = { activeStudyDeckId = null },
        modifier = modifier
      )
    } else {
      FlashcardMainView(
        viewModel = viewModel,
        metrics = metrics,
        onBackToExtras = { isFlashcardsOpen = false },
        onStartReview = { deck -> activeStudyDeckId = deck.id },
        modifier = modifier
      )
    }
    return
  }

  val deckCount = viewModel.flashcardDecks.size
  val totalCardCount = viewModel.flashcardDecks.sumOf { it.cards.size }

  Box(
    modifier = modifier.fillMaxSize(),
    contentAlignment = Alignment.TopCenter
  ) {
    Column(
      modifier = Modifier
        .fillMaxSize()
        .widthIn(max = 680.dp)
        .align(Alignment.TopCenter)
        .verticalScroll(rememberScrollState())
        .padding(
          start = metrics.scaledDp(20),
          end = metrics.scaledDp(20),
          top = metrics.scaledDp(24),
          bottom = metrics.scaledDp(116)
        )
        .testTag("extras_tools_page"),
      verticalArrangement = Arrangement.spacedBy(metrics.scaledDp(18)),
      horizontalAlignment = Alignment.CenterHorizontally
    ) {
      // Top Header
      Text(
        text = stringResource(R.string.extras_screen_title),
        style = MaterialTheme.typography.headlineLarge.copy(
          fontSize = metrics.scaledSp(26),
          fontWeight = FontWeight.Bold
        ),
        color = palette.textPrimary,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        modifier = Modifier
          .fillMaxWidth()
          .testTag("extras_screen_title")
      )

      // 1. TOP HERO CARD: Smart Flashcards Premier Featured Card
      LiquidGlassCard(
        onClick = {
          playCardHapticSound(context, localView)
