    name = "Regular Polygons",
    accentColor = Color(0xFFEC4899),
    formulas = listOf(
      PlaneGeometryFormulaItem(
        title = "Sum of Interior Angles",
        formula = "[ Σ = 180°(n - 2) ]"
      ),
      PlaneGeometryFormulaItem(
        title = "Single Interior Angle",
        formula = "[ θ = 180°(n - 2) / n ]"
      ),
      PlaneGeometryFormulaItem(
        title = "Perimeter",
        formula = "[ P = n · s ]"
      ),
      PlaneGeometryFormulaItem(
        title = "Area (Using Apothem 'a')",
        formula = "[ A = ½Pa ]"
      ),
