          singleLine = true,
          shape = RoundedCornerShape(16.dp),
          colors = sibilOutlinedTextFieldColors(),
          modifier = Modifier
            .fillMaxWidth()
            .testTag("custom_formula_category_input")
        )

        OutlinedTextField(
          value = topic,
          onValueChange = {
            topic = it
            errorText = null
          },
          label = { Text("Topic") },
          placeholder = { Text("e.g., Fluid Properties, Algebra, Trigonometry") },
          singleLine = true,
          shape = RoundedCornerShape(16.dp),
          colors = sibilOutlinedTextFieldColors(),
          modifier = Modifier
            .fillMaxWidth()
